insert into public.word_examples (word_id, order_index, sentence_en, sentence_vi) values
('00000801-0000-4000-8000-000000000801', 1, 'There is a small shop on the corner.', 'Có một cửa hàng nhỏ ở góc phố.'),
('00000801-0000-4000-8000-000000000801', 2, 'We shop for food every Saturday.', 'Chúng tôi đi mua thực phẩm vào mỗi thứ Bảy.'),
('00000801-0000-4000-8000-000000000801', 3, 'The shop closes at nine.', 'Cửa hàng đóng cửa lúc chín giờ.'),
('00000802-0000-4000-8000-000000000802', 1, 'This store sells everything for the kitchen.', 'Cửa hiệu này bán đủ thứ cho nhà bếp.'),
('00000802-0000-4000-8000-000000000802', 2, 'The store is having a big sale.', 'Cửa hiệu đang có đợt giảm giá lớn.'),
('00000802-0000-4000-8000-000000000802', 3, 'I work at a convenience store.', 'Tôi làm ở một cửa hàng tiện lợi.'),
('00000803-0000-4000-8000-000000000803', 1, 'The shopkeeper knows all his customers.', 'Chủ tiệm biết hết khách quen của mình.'),
('00000803-0000-4000-8000-000000000803', 2, 'She asked the shopkeeper for a bag.', 'Cô ấy xin chủ tiệm một cái túi.'),
('00000803-0000-4000-8000-000000000803', 3, 'The shopkeeper opens early every day.', 'Chủ tiệm mở cửa sớm mỗi ngày.'),
('00000804-0000-4000-8000-000000000804', 1, 'Pay the cashier over there.', 'Hãy thanh toán với thu ngân ở đằng kia.'),
('00000804-0000-4000-8000-000000000804', 2, 'The cashier gave me the wrong change.', 'Thu ngân đã thối nhầm tiền cho tôi.'),
('00000804-0000-4000-8000-000000000804', 3, 'She works as a cashier on weekends.', 'Cô ấy làm thu ngân vào cuối tuần.'),
('00000805-0000-4000-8000-000000000805', 1, 'There is a long line at the checkout.', 'Có một hàng dài ở quầy tính tiền.'),
('00000805-0000-4000-8000-000000000805', 2, 'Take your basket to the checkout.', 'Mang giỏ hàng của bạn ra quầy tính tiền.'),
('00000805-0000-4000-8000-000000000805', 3, 'The checkout closes in ten minutes.', 'Quầy tính tiền đóng sau mười phút nữa.'),
('00000806-0000-4000-8000-000000000806', 1, 'Leave the money on the counter.', 'Để tiền lên quầy.'),
('00000806-0000-4000-8000-000000000806', 2, 'She stood behind the counter all day.', 'Cô ấy đứng sau quầy cả ngày.'),
('00000806-0000-4000-8000-000000000806', 3, 'Ask at the information counter.', 'Hãy hỏi ở quầy thông tin.'),
('00000807-0000-4000-8000-000000000807', 1, 'Keep the receipt in case you return it.', 'Giữ hoá đơn phòng khi bạn trả hàng.'),
('00000807-0000-4000-8000-000000000807', 2, 'Can I have a receipt, please?', 'Cho tôi xin hoá đơn được không?'),
